import { test, expect } from '@playwright/test';

test.describe('Dynamic Loading Page - Async Content Reveal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  test('should reveal hidden content after asynchronous load', async ({ page }) => {
    // Verify initial state
    const finishElement = page.getByRole('button', { name: /finish/i });
    await expect(finishElement).toBeHidden();

    const startButton = page.getByRole('button', { name: /start/i });
    await expect(startButton).toBeVisible();

    // Click Start button
    await startButton.click();

    // Verify loading indicator appears
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).toBeVisible();

    // Wait for loading to complete (up to 10 seconds)
    await page.waitForTimeout(10000);

    // Verify loading indicator disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify finish element is now visible
    await expect(finishElement).toBeVisible();

    // Verify finish element contains expected text
    await expect(finishElement).toContainText('Hello World!');
  });

  test('should handle slow loading and still reveal content', async ({ page }) => {
    // Intercept the API call to simulate a slow response
    await page.route('**/api/load-content', (route) => {
      setTimeout(() => {
        route.continue();
      }, 15000);
    });

    // Click Start button
    const startButton = page.getByRole('button', { name: /start/i });
    await startButton.click();

    // Verify loading indicator appears
    const loadingIndicator = page.getByText(/loading/i);
    await expect(loadingIndicator).toBeVisible();

    // Wait for the slow response (15 seconds)
    await page.waitForTimeout(15500);

    // Verify loading indicator disappears
    await expect(loadingIndicator).not.toBeVisible();

    // Verify finish element is now visible
    const finishElement = page.getByRole('button', { name: /finish/i });
    await expect(finishElement).toBeVisible();

    // Verify finish element contains expected text
    await expect(finishElement).toContainText('Hello World!');
  });
});
